import torch
from torch import nn

class Regressor(nn.Module):
    def __init__(self, width: int = 16):
        super().__init__()
        self.layers = nn.Sequential(nn.Linear(1, width), nn.Tanh(), nn.Linear(width, 1))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.layers(x)

model = Regressor().eval()
example = torch.randn(32, 1)
with torch.inference_mode():
    eager_output = model(example)

try:
    compiled = torch.compile(model)
    with torch.inference_mode():
        compiled_output = compiled(example)
except RuntimeError as error:
    print("Optional compilation is unavailable in this environment:", error)
else:
    torch.testing.assert_close(eager_output, compiled_output, rtol=1e-4, atol=1e-5)
